// Breakpoints of |x-1| + |x+4| on the real line.
// size(W,H) bounds the output under Asymptote's default keepAspect and does not
// scale labels, so the compiler decides the box. This declaration is restated from
// a real compile by `npm run content:figures -- --record-aspect-ratios`.
size(320,120);
pair A=(-5.6,0), B=(3.8,0);
draw(A--B,Arrow);
label("$x$",B,SE);
for (int x = -5; x <= 3; ++x) {
  draw((x,-0.12)--(x,0.12),gray);
}
label("$-4$",(-4,-0.55),S);
label("$1$",(1,-0.55),S);
label("$|x-1|+|x+4|$",(-1.5,1.1),N);
dot((-4,0), black+2.5pt);
dot((1,0), black+2.5pt);
label("minimised at $x=-1.5$",(-0.5,2.4),N);
label("flat between the breakpoints",(-0.5,-2.4),S);
